import csv
import io
import re


def parse_csv(raw_csv: str):
    expected_width = 8
    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=";",
        quotechar='"',
        doublequote=True,
        strict=False,
    )

    records = []
    try:
        records.extend(reader)
    except csv.Error:
        pass

    records = [row for row in records if row and any(cell.strip() for cell in row)]
    if not records:
        return {"columns": [], "rows": []}

    def header_score(row):
        score = 0
        for cell in row:
            value = cell.strip()
            if not value:
                continue
            if re.search(r"[A-Za-z]", value) and not re.fullmatch(r"[+-]?\d+(?:\.\d+)?", value):
                score += 1
            if re.fullmatch(r"[A-Z][A-Z0-9_]*", value) or "_" in value:
                score += 1
        if row and not row[0].strip():
            score += 1
        return score

    candidates = [
        (index, row)
        for index, row in enumerate(records)
        if abs(len(row) - expected_width) <= 1
    ]

    header_index = None
    if candidates:
        strong = [
            (index, row)
            for index, row in candidates
            if header_score(row) >= max(4, expected_width)
        ]
        if strong:
            header_index = strong[0][0]
        else:
            header_index = max(candidates, key=lambda item: (header_score(item[1]), -item[0]))[0]
    else:
        header_index = 0

    def fit_width(row, width):
        row = list(row)
        if len(row) < width:
            row.extend([""] * (width - len(row)))
        elif len(row) > width:
            row = row[:width - 1] + [";".join(row[width - 1:])]
        return row

    columns = fit_width(records[header_index], expected_width)
    rows = [
        fit_width(row, len(columns))
        for row in records[header_index + 1:]
    ]
    return {"columns": columns, "rows": rows}
